<template>
  <section class="card execution-policies" aria-label="即梦账号授权">
    <header><div><h2>账号使用权限</h2><p>给创作者分配可用账号；每部作品使用自己的画布。</p></div><button type="button" class="btn btn-sm" :disabled="busy" @click="load"><RefreshCw :size="12" :class="{'animate-spin':loading}" />刷新账号</button></header>
    <p v-if="error" class="policies-error" role="alert">{{ error }}</p><p v-if="notice" class="policies-success" role="status">{{ notice }}</p>
    <p v-if="loading&&!loaded" class="policies-empty"><Loader2 :size="14" class="animate-spin" />正在读取账号与授权…</p>
    <template v-else-if="loaded"><p v-if="legacyDefaults" class="policies-hint">尚未单独配置权限，目前沿用连接的默认账号。保存后以这里的授权为准。</p><div v-if="!accounts.length" class="policies-empty">执行平台暂无账号。请先在执行平台添加并检查账号，然后刷新。</div>
      <article v-for="account in accounts" :key="account.id" class="policy-account">
        <div class="policy-account-heading"><span class="policy-avatar"><Users :size="16" /></span><div><strong>{{ account.name||account.id }}</strong><small>{{ accountState(account.state) }}</small></div><label class="policy-enabled"><input type="checkbox" v-model="drafts[account.id].enabled" :disabled="busy" />允许使用</label></div>
        <div class="policy-account-body"><div class="policy-scope"><label><span>哪些用户可以用</span><select class="input" v-model="drafts[account.id].access" :disabled="busy||!drafts[account.id].enabled"><option value="all">全部用户</option><option value="selected">指定用户</option></select></label><label class="policy-create"><input type="checkbox" v-model="drafts[account.id].allow_create" :disabled="busy||!drafts[account.id].enabled" />允许用户新建项目画布</label></div>
          <div v-if="drafts[account.id].access==='selected'" class="policy-users"><label v-for="user in creatorUsers" :key="user.id"><input type="checkbox" v-model="drafts[account.id].user_ids" :value="Number(user.id)" :disabled="busy||!drafts[account.id].enabled" /><span>{{ user.displayName||user.display_name||user.username }}</span><small>@{{ user.username }}{{ user.role==='admin'?' · 管理员':'' }}{{ user.enabled===false?' · 已停用':'' }}</small></label><p v-if="!creatorUsers.length">暂无可授权账号。</p></div>
          <details class="policy-canvases"><summary>授权已有画布 <span>{{ drafts[account.id].canvas_grants.length }} 个</span></summary><p>只把指定画布开放给选中的用户。已属于其他项目的画布仍不能重复绑定。</p>
            <div v-for="(grant,index) in drafts[account.id].canvas_grants" :key="grant.uiKey" class="canvas-grant"><div class="canvas-grant-top"><select class="input" v-model="grant.canvas_id" :disabled="busy"><option value="">选择这个账号下的画布</option><option v-for="canvas in account.projects||[]" :key="canvas.id" :value="String(canvas.id)">{{ canvas.name||canvas.id }} · {{ canvas.id }}</option></select><button type="button" class="btn btn-icon btn-sm" aria-label="移除画布授权" :disabled="busy" @click="drafts[account.id].canvas_grants.splice(index,1)"><Trash2 :size="13" /></button></div><div class="policy-users canvas-users"><label v-for="user in creatorUsers" :key="user.id"><input type="checkbox" v-model="grant.user_ids" :value="Number(user.id)" :disabled="busy" />{{ user.displayName||user.display_name||user.username }}<small>{{ user.role==='admin'?'管理员':'' }}{{ user.enabled===false?' · 已停用':'' }}</small></label><p v-if="!grant.user_ids.length">未选择用户，该画布不会开放给创作者。</p></div></div>
            <button type="button" class="btn btn-sm" :disabled="busy||!account.projects?.length" @click="addCanvasGrant(account.id)"><Plus :size="12" />授权一个画布</button>
          </details>
        </div>
      </article>
      <footer><p>账号凭据留在服务端。用户只能选择获准的账号和画布，已有作品不会因权限修改而自动换号。</p><button type="button" class="btn btn-primary" :disabled="busy" @click="save"><Loader2 v-if="saving" :size="13" class="animate-spin" />{{ saving?'正在保存…':'保存账号权限' }}</button></footer>
    </template>
  </section>
</template>
<script setup>
import {computed,ref,reactive,watch,onBeforeUnmount} from 'vue'
import {RefreshCw,Loader2,Users,Plus,Trash2} from 'lucide-vue-next'
import {api,platformUserAPI} from '~/composables/useApi'
import {platformSession} from '~/utils/platform-session'
const props=defineProps({configId:{type:[Number,String],required:true},refreshToken:{type:Number,default:0}})
const accounts=ref([]),users=ref([]),drafts=reactive({}),loading=ref(false),saving=ref(false),loaded=ref(false),legacyDefaults=ref(false),error=ref(''),notice=ref('')
let alive=true,revision=0,grantSequence=0
const busy=computed(()=>loading.value||saving.value)
// Project authorization follows the owner, including administrator-owned work.
// Keep disabled accounts visible so existing grants can still be removed.
const creatorUsers=computed(()=>users.value)
const identity=()=>`${props.configId}|${platformSession.revision}`
const current=(key,turn)=>alive&&identity()===key&&revision===turn
const accountState=state=>({ready:'已就绪',choose_canvas:'已登录',login_required:'需要重新登录'}[state]||'待检查')
function setDrafts(value){for(const key of Object.keys(drafts))delete drafts[key];const policies=value.policies||[];for(const account of value.accounts||[]){const original=policies.find(item=>item.account_id===account.id);drafts[account.id]={account_id:account.id,enabled:original?.enabled??false,access:original?.access||'selected',user_ids:[...(original?.user_ids||[])],allow_create:original?.allow_create??true,canvas_grants:(original?.canvas_grants||[]).map(grant=>({...grant,user_ids:[...(grant.user_ids||[])],uiKey:++grantSequence}))}}}
async function load(){const key=identity(),turn=++revision;loading.value=true;error.value='';notice.value='';if(!Number.isSafeInteger(Number(props.configId))||Number(props.configId)<1){loading.value=false;loaded.value=false;return}try{const [value,list]=await Promise.all([api.get(`/admin/execution/services/${Number(props.configId)}/account-policies`),platformUserAPI.list()]);if(!current(key,turn))return;accounts.value=value.accounts||[];users.value=Array.isArray(list)?list:list.users||list.items||[];legacyDefaults.value=!!value.legacy_defaults;setDrafts(value);loaded.value=true}catch(e){if(current(key,turn))error.value=e.message||'读取账号权限失败。'}finally{if(current(key,turn))loading.value=false}}
function addCanvasGrant(accountId){if(busy.value||!drafts[accountId])return;drafts[accountId].canvas_grants.push({canvas_id:'',user_ids:[],uiKey:++grantSequence})}
async function save(){if(busy.value||!loaded.value)return;const key=identity(),turn=revision;saving.value=true;error.value='';notice.value='';try{const policies=accounts.value.map(account=>{const draft=drafts[account.id];if(draft.canvas_grants.some(grant=>!grant.canvas_id))throw Error('请先选择已有画布，或移除空的画布授权。');const canvases=draft.canvas_grants.map(grant=>({canvas_id:grant.canvas_id,user_ids:[...grant.user_ids]}));if(new Set(canvases.map(grant=>grant.canvas_id)).size!==canvases.length)throw Error('同一个账号的画布不能重复授权，请合并勾选用户。');return{account_id:account.id,enabled:!!draft.enabled,access:draft.access,user_ids:draft.access==='selected'?[...draft.user_ids]:[],allow_create:!!draft.allow_create,canvas_grants:canvases}});await api.put(`/admin/execution/services/${Number(props.configId)}/account-policies`,{policies});if(!current(key,turn))return;legacyDefaults.value=false;notice.value='账号权限已保存，用户可在自己项目中选择。'}catch(e){if(current(key,turn))error.value=e.message||'权限未保存，请重试。'}finally{if(current(key,turn))saving.value=false}}
watch(()=>[props.configId,props.refreshToken,platformSession.revision],()=>{revision++;loaded.value=false;accounts.value=[];saving.value=false;for(const key of Object.keys(drafts))delete drafts[key];void load()},{immediate:true})
onBeforeUnmount(()=>{alive=false;revision++})
</script>
<style scoped>
.execution-policies{padding:24px;margin-bottom:20px}.execution-policies>header{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:20px}.execution-policies h2{font-size:17px;margin:0 0 7px}.execution-policies p{font-size:11px;line-height:1.8;color:var(--text-3);margin:0}.policy-account{border:1px solid var(--border);border-radius:12px;margin-top:12px;overflow:hidden}.policy-account-heading{display:flex;align-items:center;gap:10px;padding:15px 18px;background:var(--bg-0)}.policy-avatar{display:grid;place-items:center;height:32px;width:32px;color:var(--accent-text);background:var(--accent-bg);border-radius:9px}.policy-account-heading strong{font-size:12px}.policy-account-heading small{display:block;font-size:10px;color:var(--text-3);margin-top:4px}.policy-enabled{margin-left:auto;display:flex;align-items:center;gap:6px;font-size:11px;white-space:nowrap}.policy-account-body{padding:17px 18px}.policy-scope{display:grid;grid-template-columns:minmax(170px,1fr) minmax(200px,1fr);gap:18px;align-items:center}.policy-scope>label:first-child{display:grid;gap:7px;font-size:11px;color:var(--text-2)}.policy-scope .input,.canvas-grant .input{font-size:12px;height:37px}.policy-create{display:flex;align-items:center;gap:7px;font-size:11px}.execution-policies input[type=checkbox]{accent-color:var(--accent);width:13px;height:13px}.policy-users{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:9px;margin-top:13px;padding:13px;border:1px solid var(--border);border-radius:8px;max-height:180px;overflow:auto}.policy-users label{font-size:11px;display:flex;align-items:center;gap:6px}.policy-users small{font-size:9px;color:var(--text-3)}.policy-canvases{margin-top:17px;padding-top:15px;border-top:1px solid var(--border)}.policy-canvases summary{font-size:11px;cursor:pointer;color:var(--text-2)}.policy-canvases summary span{margin-left:6px;color:var(--text-3)}.policy-canvases>p{margin:10px 0}.canvas-grant{padding:12px;background:var(--bg-0);border-radius:9px;margin-bottom:10px}.canvas-grant-top{display:flex;align-items:center;gap:8px}.canvas-grant-top select{flex:1;min-width:0}.canvas-users{background:var(--bg-1);max-height:160px;margin-top:10px}.execution-policies>footer{display:flex;justify-content:space-between;gap:20px;align-items:center;border-top:1px solid var(--border);padding-top:18px;margin-top:20px}.execution-policies footer p{max-width:70%}.policies-error,.policies-success,.policies-hint{padding:10px 13px;border-radius:9px;margin:12px 0!important}.execution-policies .policies-error{color:var(--error);background:var(--error-bg)}.execution-policies .policies-success{color:var(--success);background:var(--success-bg)}.policies-hint{background:var(--accent-bg);color:var(--accent-text)!important}.policies-empty{padding:12px;display:flex;gap:8px;align-items:center}@media(max-width:750px){.execution-policies{padding:18px}.policy-scope{grid-template-columns:1fr;gap:12px}.policy-users{grid-template-columns:1fr}.execution-policies>footer{align-items:flex-start;flex-direction:column}.execution-policies footer p{max-width:100%}}
</style>
